import re

HARF = str.maketrans("\u0131\u0130\u015f\u015e\u011f\u011e\u00fc\u00dc\u00f6\u00d6\u00e7\u00c7", "iissgguuoocc")

def normalize(s):
    s = str(s).translate(HARF).lower()
    s = re.sub(r"['`\u00b4\u2019\u2018]", "", s)
    s = re.sub(r"[^0-9a-z]+", " ", s)
    return s.strip()

OLUMSUZ = ("degil", "yok", "hayir", "not")

def kabul_mu(cevap, kabuller):
    n = normalize(cevap)
    if not n:
        return False
    for a in (normalize(x) for x in kabuller):
        if not a:
            continue
        if n == a:
            return True
        if " " + a + " " in " " + n + " ":
            if any(" " + o + " " in " " + n + " " and " " + o + " " not in " " + a + " " for o in OLUMSUZ):
                continue
            return True
    return False

KABUL = ["yigin", "stack"]
for c in ["Y\u0131\u011f\u0131n", "YI\u011eIN", "y\u0131\u011f\u0131n de\u011fil", "y\u0131\u011f\u0131nlar", "stack yap\u0131s\u0131", "kuyruk"]:
    print(normalize(c), "->", kabul_mu(c, KABUL))

