# SM-2 (js/srs.js ile ayni mantik)
def yeni_kart():
    return {"ef": 2.5, "interval": 0, "reps": 0, "lapses": 0}

def review(kart, q):
    c = dict(kart)
    if q < 3:
        c["reps"] = 0
        c["lapses"] += 1
        c["interval"] = 0
    else:
        c["reps"] += 1
        if c["reps"] == 1:
            c["interval"] = 1
        elif c["reps"] == 2:
            c["interval"] = 6
        else:
            c["interval"] = round(c["interval"] * c["ef"])
    if q >= 3:
        c["ef"] = max(1.3, c["ef"] + (0.1 - (5 - q) * (0.08 + (5 - q) * 0.02)))
    return c

k = yeni_kart()
for q in [4, 4, 5, 3, 0, 4]:
    k = review(k, q)
    print("q=", q, "reps=", k["reps"], "lapses=", k["lapses"], "aralik=", k["interval"], "ef=", round(k["ef"], 2))
